"use client";

import { useEffect, useState } from "react";

export default function Navbar() {
  const [menuOpen, setMenuOpen] = useState(false);
  const [darkMode, setDarkMode] = useState(false);

  useEffect(() => {
    const savedTheme = localStorage.getItem("theme");

    if (savedTheme === "dark") {
      setDarkMode(true);
      document.documentElement.classList.add("dark-mode");
    }
  }, []);

  const toggleDarkMode = () => {
    const nextMode = !darkMode;

    setDarkMode(nextMode);

    if (nextMode) {
      document.documentElement.classList.add("dark-mode");
      localStorage.setItem("theme", "dark");
    } else {
      document.documentElement.classList.remove("dark-mode");
      localStorage.setItem("theme", "light");
    }
  };

  return (
    <header className="navbar">
      <div className="navbar-inner">

        {/* LOGO */}
        <div className="logo">
          <span className="logo-symbol">♧</span>
          <span className="logo-text">airbnb</span>
        </div>

        {/* NAV */}
        <nav className="desktop-nav">
          <button className="nav-category active">
            <span className="nav-category-icon">🌍</span>
            <span>All</span>
          </button>

          <button className="nav-category">
            <span className="nav-category-icon">🏠</span>
            <span>Homes</span>
          </button>

          <button className="nav-category">
            <span className="nav-category-icon">🎈</span>
            <span>Experiences</span>
          </button>

          <button className="nav-category">
            <span className="nav-category-icon">🛎️</span>
            <span>Services</span>
          </button>
        </nav>

        {/* RIGHT */}
        <div className="navbar-right">

          <button className="host-link">
            Become a host
          </button>

          <button
            className="profile-avatar"
            onClick={() => setMenuOpen((prev) => !prev)}
            aria-label="Profile"
          >
            P
          </button>

          <button
            className="menu-button"
            onClick={() => setMenuOpen((prev) => !prev)}
            aria-label="Menu"
          >
            <span className="menu-lines">☰</span>
          </button>

        </div>

        {/* PROFILE DROPDOWN */}
        {menuOpen && (
          <>
            <div
              className="menu-overlay"
              onClick={() => setMenuOpen(false)}
            />

            <div className="profile-menu">

              <button className="profile-menu-item highlighted">
                <span className="menu-item-icon">♡</span>
                <span>Wishlists</span>
              </button>

              <button className="profile-menu-item">
                <span className="menu-item-icon">♧</span>
                <span>Trips</span>
              </button>

              <button className="profile-menu-item">
                <span className="menu-item-icon">▢</span>
                <span>Messages</span>
              </button>

              <button className="profile-menu-item">
                <span className="menu-item-icon">◎</span>
                <span>Profile</span>
              </button>

              <div className="menu-divider" />

              <button className="profile-menu-item">
                <span className="menu-item-icon">♧</span>
                <span>Notifications</span>
              </button>

              <button className="profile-menu-item">
                <span className="menu-item-icon">⚙</span>
                <span>Account settings</span>
              </button>

              <button className="profile-menu-item">
                <span className="menu-item-icon">🌐</span>
                <span>Languages &amp; currency</span>
              </button>

              <button className="profile-menu-item">
                <span className="menu-item-icon">?</span>
                <span>Help Centre</span>
              </button>

              <div className="menu-divider" />

              {/* DARK MODE */}
              <button
                className="theme-toggle-item"
                onClick={toggleDarkMode}
              >
                <span className="theme-toggle-left">
                  <span className="menu-item-icon">
                    {darkMode ? "☀️" : "🌙"}
                  </span>

                  <span>
                    {darkMode ? "Light mode" : "Dark mode"}
                  </span>
                </span>

                <span
                  className={`theme-switch ${
                    darkMode ? "theme-switch-active" : ""
                  }`}
                >
                  <span className="theme-switch-knob" />
                </span>
              </button>

              <div className="menu-divider" />

              {/* HOST */}
              <button className="host-menu-card">

                <div className="host-menu-text">
                  <strong>Become a host</strong>

                  <span>
                    It’s easy to start hosting and
                    <br />
                    earn extra income.
                  </span>
                </div>

                <div className="host-person">
                  🧑
                </div>

              </button>

              <div className="menu-divider" />

              <button className="profile-menu-item">
                <span className="menu-item-icon empty-icon" />
                <span>Refer a host</span>
              </button>

              <button className="profile-menu-item">
                <span className="menu-item-icon empty-icon" />
                <span>Find a co-host</span>
              </button>

              <div className="menu-divider" />

              <button className="profile-menu-item logout-item">
                <span className="menu-item-icon empty-icon" />
                <span>Log out</span>
              </button>

            </div>
          </>
        )}

      </div>
    </header>
  );
}